        Effect(id: "UnderwaterCaustics", name: "水下焦散", title: "Underwater Caustics", summary: "游动的水光、波纹和淡蓝色深度感覆盖画面。", parameters: [Parameter(key: "causticScale", name: "焦散尺度", initial: 6.0, lower: 2.0, upper: 15.0), Parameter(key: "causticIntensity", name: "水光强度", initial: 1.0, lower: 0.0, upper: 2.0), Parameter(key: "waterDistortion", name: "水面扭曲", initial: 12.0, lower: 0.0, upper: 30.0), Parameter(key: "waterDepth", name: "水体深度", initial: 0.4, lower: 0.0, upper: 1.0)]),
        Effect(id: "Vortex", name: "旋涡", title: "Vortex Spiral", summary: "图像围绕中心旋转、扭曲，中心与边缘转角不同。", parameters: [Parameter(key: "twistAmount", name: "扭转角度", initial: 3.0, lower: 0.0, upper: 10.0), Parameter(key: "radius", name: "作用半径", initial: 0.5, lower: 0.1, upper: 1.0), Parameter(key: "speed", name: "速度", initial: 0.5, lower: 0.1, upper: 3.0), Parameter(key: "falloff", name: "距离衰减", initial: 2.0, lower: 0.5, upper: 5.0)]),
        Effect(id: "WavePool", name: "波浪池", title: "Wave Pool", summary: "多个方向的波浪交叠，让画面像水面一样起伏。", parameters: [Parameter(key: "amplitude", name: "位移幅度", initial: 12, lower: 0.0, upper: 25.0), Parameter(key: "wavelength", name: "波长", initial: 22, lower: 5.0, upper: 40.0), Parameter(key: "speed", name: "速度", initial: 2.75, lower: 0.5, upper: 5.0), Parameter(key: "complexity", name: "叠加波数", initial: 3.5, lower: 1.0, upper: 6.0)]),
        Effect(id: "Wormhole", name: "虫洞", title: "Wormhole", summary: "画面卷进带纵深与旋转感的隧道。", parameters: [Parameter(key: "depth", name: "深度", initial: 4.5, lower: 1.0, upper: 8.0), Parameter(key: "speed", name: "速度", initial: 1.65, lower: 0.3, upper: 3.0), Parameter(key: "twist", name: "隧道扭转", initial: 2.5, lower: 0.0, upper: 5.0), Parameter(key: "radius", name: "作用半径", initial: 0.3, lower: 0.1, upper: 0.5)])
    ]
}

@main
struct ShaderGalleryApp: App {
    var body: some Scene {
        WindowGroup("SwiftUI Shader Lab · Native Metal") {
            GalleryView().frame(minWidth: 1020, minHeight: 760).preferredColorScheme(.dark)
        }
    }
}

struct GalleryView: View {
    @State private var selection = "Holographic"
    @State private var values: [String: Double] = [:]
    @State private var touch = UnitPoint.center
    @State private var touchDate: Date?
    @State private var compare = false
    private var effect: Effect { Effect.all.first { $0.id == selection } ?? Effect.all[0] }

    private func value(_ key: String) -> Double {
        values[key] ?? effect.parameters.first { $0.key == key }?.initial ?? 0
    }

    private func reset() {
        values = [:]
        touch = .center
        touchDate = nil
    }

    private var cover: some View {
        Image("sample-cover").resizable().scaledToFit().frame(width: 360, height: 480)
    }

    var body: some View {
        HStack(spacing: 0) {
            List(selection: $selection) {
                ForEach(Effect.all) { item in
                    VStack(alignment: .leading, spacing: 4) {
                        Text(item.name).font(.headline)
                        Text(item.title).font(.caption).foregroundStyle(.secondary)
                    }.padding(.vertical, 6).tag(item.id)
                }
            }.frame(width: 220)
            VStack(spacing: 22) {
                Text(effect.name).font(.largeTitle)
                Text(effect.title).foregroundStyle(.secondary)
                Group {
                    if compare { cover }
                    else if selection == "TouchRipple" {
                        TimelineView(.animation) { context in
                            applied(cover, age: touchDate.map { context.date.timeIntervalSince($0) } ?? value("touchAge"))
                        }
                    } else { applied(cover, age: value("touchAge")) }
                }
                .contentShape(Rectangle())
                .gesture(DragGesture(minimumDistance: 0).onChanged { drag in
                    touch = UnitPoint(x: min(1, max(0, drag.location.x / 360)),
                                      y: min(1, max(0, drag.location.y / 480)))
                    touchDate = Date()
                })
                .shadow(radius: 20)
                Toggle("显示原图", isOn: $compare).toggleStyle(.switch).frame(width: 150)
                Text("原始 Metal · 41 个公开修饰器 · 点击或拖动触摸交互效果")
                    .font(.caption).foregroundStyle(.secondary)
            }.frame(maxWidth: .infinity).padding(24)
            Divider()
            ScrollView {
                VStack(alignment: .leading, spacing: 20) {
                    HStack { Text("全部参数").font(.headline); Spacer(); Button("恢复默认", action: reset) }
                    Text(effect.summary).font(.callout).foregroundStyle(.secondary)
                    ForEach(effect.parameters) { parameter in
                        VStack(alignment: .leading, spacing: 7) {
                            HStack {
                                Text(parameter.name)
                                Spacer()
                                Text(value(parameter.key), format: .number.precision(.fractionLength(0...3))).monospacedDigit()
                            }.font(.callout)
                            Slider(value: Binding(get: { value(parameter.key) }, set: { values[parameter.key] = $0; if parameter.key == "touchAge" { touchDate = nil } }),
                                   in: parameter.lower...parameter.upper)
                            Text(parameter.key).font(.caption.monospaced()).foregroundStyle(.secondary)
                        }
                    }
                    if selection == "RefractLens" || selection == "TouchRipple" {
                        Text("拖动封面更新 touchPos；涟漪的 touchAge 由 TimelineView 持续推进，也可手动调节。")
                            .font(.caption).foregroundStyle(.secondary)
                    }
                    Text("与网页的 WebGL 移植预览对照时，请使用相同参数。原生默认 maxSampleOffset 为 64×64，强位移可能受到采样边界限制。")
                        .font(.caption).foregroundStyle(.secondary)
                    Link("查看上游源码 ↗", destination: URL(string: "https://github.com/krispuckett/SwiftUIShaders/tree/6b644a8bd4f3131401bd6765990e476352d3cdef")!)
                }.padding(22)
            }.frame(width: 300)
        }
        .onChange(of: selection) { _, _ in reset() }
    }

    private func applied<V: View>(_ content: V, age: Double) -> AnyView {
        switch selection {
        case "Aurora": return AnyView(content.bcsAurora(intensity: Float(value("intensity")), bands: Float(value("bands")), speed: Float(value("speed")), colorShift: Float(value("colorShift"))))
        case "BlackHole": return AnyView(content.bcsBlackHole(mass: Float(value("mass")), spin: Float(value("spin")), distortion: Float(value("distortion")), ringBrightness: Float(value("ringBrightness"))))
        case "ChromaticSplit": return AnyView(content.bcsChromaticSplit(spread: Float(value("spread")), angle: Float(value("angle")), edgeOnly: Float(value("edgeOnly")), animate: Float(value("animate"))))
        case "Datamosh": return AnyView(content.bcsDatamosh(blockCorruption: Float(value("blockCorruption")), smearAmount: Float(value("smearAmount")), colorBleed: Float(value("colorBleed")), glitchRate: Float(value("glitchRate"))))
        case "Disintegrate": return AnyView(content.bcsDisintegrate(threshold: Float(value("threshold")), edgeWidth: Float(value("edgeWidth")), driftAmount: Float(value("driftAmount")), direction: Float(value("direction"))))
        case "Duochrome": return AnyView(content.bcsDuochrome(intensity: Float(value("intensity")), hue1: Float(value("hue1")), hue2: Float(value("hue2")), contrast: Float(value("contrast"))))
        case "Echo": return AnyView(content.bcsEcho(echoCount: Float(value("echoCount")), spread: Float(value("spread")), direction: Float(value("direction")), fade: Float(value("fade"))))
        case "Emboss": return AnyView(content.bcsEmboss(strength: Float(value("strength")), angle: Float(value("angle")), mixAmount: Float(value("mixAmount"))))
        case "EtherealAura": return AnyView(content.bcsEtherealAura(auraWidth: Float(value("auraWidth")), auraIntensity: Float(value("auraIntensity")), pulseSpeed: Float(value("pulseSpeed")), distortion: Float(value("distortion")), hueShift: Float(value("hueShift"))))
        case "Frosted": return AnyView(content.bcsFrosted(frostAmount: Float(value("frostAmount")), grainSize: Float(value("grainSize")), clearRadius: Float(value("clearRadius")), clearSoftness: Float(value("clearSoftness"))))
        case "GeometricWarp": return AnyView(content.bcsGeometricWarp(spiralTight: Float(value("spiralTight")), zoomRepeat: Float(value("zoomRepeat")), rotation: Float(value("rotation")), blend: Float(value("blend"))))
        case "Glitch": return AnyView(content.bcsGlitch(intensity: Float(value("intensity")), blockSize: Float(value("blockSize")), scanLines: Float(value("scanLines")), colorShift: Float(value("colorShift"))))
        case "GravityWells": return AnyView(content.bcsGravityWells(wellStrength: Float(value("wellStrength")), wellCount: Float(value("wellCount")), orbitSpeed: Float(value("orbitSpeed")), warpFalloff: Float(value("warpFalloff"))))
        case "HeatShimmer": return AnyView(content.bcsHeatShimmer(amplitude: Float(value("amplitude")), frequency: Float(value("frequency")), speed: Float(value("speed")), verticalBias: Float(value("verticalBias"))))
        case "Holographic": return AnyView(content.bcsHolographic(intensity: Float(value("intensity")), scale: Float(value("scale")), speed: Float(value("speed")), angleOffset: Float(value("angleOffset"))))
        case "InkBleed": return AnyView(content.bcsInkBleed(warpStrength: Float(value("warpStrength")), scale: Float(value("scale")), speed: Float(value("speed")), detail: Float(value("detail"))))
        case "Kaleidoscope": return AnyView(content.bcsKaleidoscope(segments: Float(value("segments")), rotation: Float(value("rotation")), zoom: Float(value("zoom")), animateSpeed: Float(value("animateSpeed"))))
        case "LiquidChrome": return AnyView(content.bcsLiquidChrome(distortion: Float(value("distortion")), chromeIntensity: Float(value("chromeIntensity")), flowSpeed: Float(value("flowSpeed")), reflectionScale: Float(value("reflectionScale"))))
        case "LiquidMirror": return AnyView(content.bcsLiquidMirror(mirrorAxis: Float(value("mirrorAxis")), ripple: Float(value("ripple")), speed: Float(value("speed")), depth: Float(value("depth"))))
        case "LiveRipple": return AnyView(content.bcsLiveRipple(amplitude: Float(value("amplitude")), frequency: Float(value("frequency")), speed: Float(value("speed")), damping: Float(value("damping")), ringCount: Float(value("ringCount"))))
        case "MagneticField": return AnyView(content.bcsMagneticField(fieldStrength: Float(value("fieldStrength")), lineCount: Float(value("lineCount")), fieldTurbulence: Float(value("fieldTurbulence")), polarity: Float(value("polarity"))))
        case "Melt": return AnyView(content.bcsMelt(meltAmount: Float(value("meltAmount")), dripScale: Float(value("dripScale")), speed: Float(value("speed")), heat: Float(value("heat"))))
        case "MorphBreathe": return AnyView(content.bcsMorphBreathe(breatheDepth: Float(value("breatheDepth")), breatheRate: Float(value("breatheRate")), warpComplexity: Float(value("warpComplexity")), organic: Float(value("organic"))))
        case "NeonEdge": return AnyView(content.bcsNeonEdge(edgeStrength: Float(value("edgeStrength")), glowAmount: Float(value("glowAmount")), colorCycle: Float(value("colorCycle")), mixOriginal: Float(value("mixOriginal"))))
        case "PixelateMosaic": return AnyView(content.bcsPixelateMosaic(pixelSize: Float(value("pixelSize")), bevel: Float(value("bevel")), animateAssemble: Float(value("animateAssemble")), gap: Float(value("gap"))))
        case "PixelateStorm": return AnyView(content.bcsPixelateStorm(pixelSize: Float(value("pixelSize")), stormAmount: Float(value("stormAmount")), swirl: Float(value("swirl")), pulse: Float(value("pulse"))))
        case "Plasma": return AnyView(content.bcsPlasma(intensity: Float(value("intensity")), scale: Float(value("scale")), speed: Float(value("speed")), colorMode: Float(value("colorMode"))))
        case "Pulse": return AnyView(content.bcsPulse(amplitude: Float(value("amplitude")), bpm: Float(value("bpm")), sharpness: Float(value("sharpness")), glowIntensity: Float(value("glowIntensity"))))
        case "RefractLens": return AnyView(content.bcsRefractLens(touchPos: touch, lensRadius: Float(value("lensRadius")), refraction: Float(value("refraction")), aberration: Float(value("aberration")), wobble: Float(value("wobble"))))
        case "Shatter": return AnyView(content.bcsShatter(shardCount: Float(value("shardCount")), explode: Float(value("explode")), rotationAmt: Float(value("rotationAmt")), edgeGlow: Float(value("edgeGlow"))))
        case "ShatterGlass": return AnyView(content.bcsShatterGlass(crackDensity: Float(value("crackDensity")), glassRefraction: Float(value("glassRefraction")), prismStrength: Float(value("prismStrength")), shatterSpread: Float(value("shatterSpread"))))
        case "Shockwave": return AnyView(content.bcsShockwave(waveSpeed: Float(value("waveSpeed")), ringWidth: Float(value("ringWidth")), strength: Float(value("strength")), repeatRate: Float(value("repeatRate"))))
        case "SmokeReveal": return AnyView(content.bcsSmokeReveal(smokeAmount: Float(value("smokeAmount")), smokeScale: Float(value("smokeScale")), windSpeed: Float(value("windSpeed")), smokeTurb: Float(value("smokeTurb"))))
        case "Solarize": return AnyView(content.bcsSolarize(threshold: Float(value("threshold")), curveIntensity: Float(value("curveIntensity")), colorSeparation: Float(value("colorSeparation")), animate: Float(value("animate"))))
        case "Thermal": return AnyView(content.bcsThermal(intensity: Float(value("intensity")), shimmer: Float(value("shimmer")), noiseSpeed: Float(value("noiseSpeed")), paletteShift: Float(value("paletteShift"))))
        case "Topographic": return AnyView(content.bcsTopographic(lineCount: Float(value("lineCount")), lineWidth: Float(value("lineWidth")), colorize: Float(value("colorize")), animate: Float(value("animate"))))
        case "TouchRipple": return AnyView(content.bcsTouchRipple(touchPos: touch, touchAge: Float(age), amplitude: Float(value("amplitude")), frequency: Float(value("frequency")), speed: Float(value("speed")), decay: Float(value("decay"))))
        case "UnderwaterCaustics": return AnyView(content.bcsUnderwaterCaustics(causticScale: Float(value("causticScale")), causticIntensity: Float(value("causticIntensity")), waterDistortion: Float(value("waterDistortion")), waterDepth: Float(value("waterDepth"))))
        case "Vortex": return AnyView(content.bcsVortex(twistAmount: Float(value("twistAmount")), radius: Float(value("radius")), speed: Float(value("speed")), falloff: Float(value("falloff"))))
        case "WavePool": return AnyView(content.bcsWavePool(amplitude: Float(value("amplitude")), wavelength: Float(value("wavelength")), speed: Float(value("speed")), complexity: Float(value("complexity"))))
        case "Wormhole": return AnyView(content.bcsWormhole(depth: Float(value("depth")), speed: Float(value("speed")), twist: Float(value("twist")), radius: Float(value("radius"))))
        default: return AnyView(content)
        }
    }
}
